import datetime,fcntl,gzip,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 plan=H/'bridge-discovery-frozen-plan-nov3.json';m=json.loads(plan.read_text());state=json.loads((H/'live-nov3-bridge-discovery-custody.json').read_text());a=json.loads((H/'live-nov3-bridge-discovery-independent-analysis.json').read_text());rows=list(a['rows'].values())
 assert sha(plan)==state['manifest_sha256'];bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad
 assert state['status']=='complete' and len(state['runs'])==9 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time']
 assert all(r['owned_descendants_remaining']==[] for r in rows)
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file());files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.exists() for p in files);assert not any(p.suffix in ['.log','.jsonl'] for p in files)
 bridge=[r for r in rows if r['arm']=='bridge'];counts={k:sum(r['bridge_acknowledgements']['bridge_counts'][k] for r in bridge) for k in bridge[0]['bridge_acknowledgements']['bridge_counts']}
 quality={'samples':'live-nov3-bridge-discovery-quality-samples.json','reviewed':6,'findings':['All three 7703 arms emit identical fenced minversion definition at index86, violating one-paragraph/no-code contract; factual LooseVersion issue is source-supported.','Bridge7703 index77 still calls repository structure correct from ls alone.','Bridge8803 index26 still overstates grep missing-path errors as an environment blocker for a union-type feature request.','Bridge9901 index6 repeats prior material timezone error: supplied code hardcodes UTC but output claims correct database-timezone handling.'],'source_grounding':'Same retained issues/latest observations already reviewed and preserved in live-nov3-triage-confirmation-quality-samples.json; no fresh source/model retrieval.','mechanical_counts':{r['name']:r['service_format'] for r in rows},'degeneracy_flags':sum(r['output_screen']['flagged'] for r in rows),'limits':'Small post-discovery inspection, not quality equivalence or autonomous task-success proof. No new conspicuous looping observed; human review remains necessary.'}
 assessment={'schema':'astra-bridge-discovery-assessment-v1','plan_sha256':sha(plan),'source_pins_unchanged':True,'all_nine_eligible':all(r['eligible'] for r in rows),'natural_eos':sum(r['natural_eos'] for r in rows),'HTTP':{'attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)},'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'first_admission_reconciles_all':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'store_accept_complete_balanced_all':all(r['store_balance']['balanced'] is True for r in rows),'explicit_store_failure_counter':'Unavailable, not assumed zero.','all_measurement_configurations_match':all(r['measurement']['matches_frozen_lean'] for r in rows),'optional_observer_counts_explicit_zero':all(all(r['measurement'][k]==0 for k in ['residency_samples','readmission_events','lookup_observer_events']) for r in rows),'bridge_acknowledgement_totals':counts,'comparisons':a['comparisons'],'resource_and_mechanism_rows':{r['name']:{k:r[k] for k in ['load_s','tokens','tokens_s','tokens_s_per_gib','ttft_ms','e2e_ms','resources','host_resources','thermal_clock_power','first_prefill_attribution','transfers','scheduler_counts','bridge_acknowledgements','configuration_activation']} for r in rows},'quality':quality,'production_endorsement':False,'judgment':'No demonstrated incremental benefit from bridge; whole-workflow rates are lower than old retention in all three single comparisons. Only one additional suffix opportunity was observed, so the proposed mechanism does not broadly address these workload regressions. Do not advance bridge to confirmation based on this screen.','limitations':['Three single workflows perarm on spent inputs, not inferential confirmation.','Natural outputs differ (7703 bridge has138 more tokens than old); do not equate token-rate change with workflow speed.','Suffix telemetry counts repeated eligible touches, not unique keys, retained lifetime or successful future demand restoration.','First-admission attribution is not cumulative physical GPU work; total transfer is reported independently.','Serving NVML7701.87–7703.87MiB, startup7953.87MiB; configured CPUKV1792MiB. No meaningful incremental memory saving.','System-wide swap and dynamic GPU clocks observed, not controlled or uniquely attributed.','Prior byte qualifications cover old geometry/source copy path, not a new transfer certificate for every bridge-induced future lifetime.','Endurance and4096-session registry saturation remain unqualified.'],'next_step_recommendation':'Cadence discovery on old hardened source is more distinct and better motivated than further bridge tuning. Compare periodic, once-positive and once-complete versus native; retain partial-prefix-growth and lost-recency-protection risks. No next runs launched.'}
 write(H/'live-nov3-bridge-discovery-independent-assessment.json',assessment)
 cadence=H/'cadence-discovery-frozen-plan-nov3.json';c=json.loads(cadence.read_text());cbad=[p for p,v in c['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v]
 review={'schema':'astra-cadence-prelaunch-review-v1','manifest_sha256':sha(cadence),'pins_checked':len(c['file_pins']),'pin_mismatches':cbad,'source_level_blocker_found':False,'requested_control_strengthening':'Positive/complete ACK test must leave pending=True and assert producer returns after exactly one POST. Existing fake client flips pending=False on final ACK, weakening claimed no-extra-POST proof. Root notified; no source changes requested.','scope':'Response-based stopping sees only already observed prefix and causal acknowledgement, not future return deadline. Fixed16-token block contract valid for these pinned runs; not generic layout support.','runners':'Per-item runners are necessary; once variants archive and import their own pinned workload. Serving/model/output/wait/history remain common; only advice cadence changes.','statistical_scope':'Three rows of a four-arm Latin rotation are not fully position-balanced; descriptive spent-input discovery only.','no_launch_performed':True};write(H/'live-nov3-cadence-astra-prelaunch-review.json',review)
 inventory={'schema':'astra-bridge-discovery-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','pins_checked':len(m['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'reason':'All raw evidence, exact per-run archives and already-compressed server/console logs retained for root independent recomputation. No disposable downloads/worktrees/checkpoints/uncompressed logs/owned processes remain; earlier/shared work untouched.'};write(H/'live-nov3-bridge-discovery-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':assessment['HTTP'],'bridge_counts':counts,'pins':len(m['file_pins']),'retained_bytes':inventory['retained_bytes'],'cadence_pin_mismatches':cbad,'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
